-- Record snapshots (#146, release B): when a patient changes type, the record's encrypted payload and the template it
-- was written against are archived read-only here. Erased with the record (cascade) and covered by pii:reencrypt.

CREATE TABLE "medical_record_snapshots" (
    "id" UUID NOT NULL,
    "medicalRecordId" UUID NOT NULL,
    "patientTypeId" UUID NOT NULL,
    "patientTypeName" VARCHAR(80) NOT NULL,
    "template" JSONB NOT NULL,
    "data" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "medical_record_snapshots_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "medical_record_snapshots_medicalRecordId_idx" ON "medical_record_snapshots"("medicalRecordId");

ALTER TABLE "medical_record_snapshots" ADD CONSTRAINT "medical_record_snapshots_medicalRecordId_fkey" FOREIGN KEY ("medicalRecordId") REFERENCES "medical_records"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- The release A copy put every clinical column into the payload, so Familia records can hold antecedents and
-- Individual records family fields that their template doesn't show. Add those keys as removed fields with today's
-- labels, so the record view shows their values under "Campos anteriores". Only types still on the release A template.

